import urllib.request,json,urllib.parse
for acc in ['ENCFF254VNR','ENCFF425CQF']:
 params={'type':'File','index_of':f'/files/{acc}/','format':'json','limit':'10'}
 url='https://www.encodeproject.org/search/?'+urllib.parse.urlencode(params)
 req=urllib.request.Request(url,headers={'accept':'application/json','user-agent':'codex-galaxy-analysis'})
 with urllib.request.urlopen(req,timeout=30) as r: data=json.load(r)
 print(acc,'total',data.get('total'))
 for g in data.get('@graph',[]): print(g.get('accession'),g.get('file_format'),g.get('href'),g.get('file_size'))
PY"

